import { Injector, InjectionToken } from '@angular/core';

let calls = 0;
const REQUEST_ID = new InjectionToken<number>('REQUEST_ID');

const injector = Injector.create({
  providers: [{ provide: REQUEST_ID, useFactory: () => ++calls }],
});

const first = injector.get(REQUEST_ID);
const second = injector.get(REQUEST_ID);
console.log(first, second, calls);

@Injectable({ providedIn: 'root' })
export class ReportService {
  private http = inject(HttpClient);

  loadReport(month: string) {
    const apiUrl = inject(API_URL);
    return this.http.get<Report>(`${apiUrl}/reports/${month}`);
  }
}

