import { signal, computed } from '@angular/core';

const items = signal([1, 2]);
const total = computed(() => items().length);

console.log(total());
items.update(list => {
  list.push(3);
  return list;
});
console.log(total());
items.update(list => [...list, 4]);
console.log(total());

@Component({
  selector: 'app-report',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<p>{{ status }}</p>`,
})
export class ReportComponent implements OnInit {
  private reports = inject(ReportService);
  status = 'Loading...';

  ngOnInit() {
    this.reports.load().subscribe(r => {
      this.status = `Loaded ${r.items.length} items`;
    });
  }
}

import { signal, computed, untracked } from '@angular/core';

const a = signal(1);
const b = signal(10);
const sum = computed(() => a() + untracked(() => b()));

console.log(sum());
b.set(20);
console.log(sum());
a.set(2);
console.log(sum());

import { of } from 'rxjs';
import { map, filter } from 'rxjs/operators';

of(1, 2, 3)
  .pipe(
    map(x => x * 10),
    filter(x => x > 10),
  )
  .subscribe(v => console.log(v));

import { Subject, BehaviorSubject } from 'rxjs';

const log: string[] = [];

const s = new Subject<number>();
s.next(1);
s.subscribe(v => log.push('A' + v));
s.next(2);

const b = new BehaviorSubject<number>(0);
b.next(1);
b.subscribe(v => log.push('B' + v));
b.next(2);

console.log(log.join(' '));

import { of, timer } from 'rxjs';
import { map, mergeMap } from 'rxjs/operators';

of(1, 2, 3)
  .pipe(
    mergeMap(x => timer(40 - x * 10).pipe(map(() => x))),
  )
  .subscribe(v => console.log(v));

@Component({
  selector: 'app-dashboard',
  template: `<app-stats [data]="stats()" />`,
})
export class DashboardComponent implements OnInit {
  private statsApi = inject(StatsService);
  stats = signal<Stats | null>(null);

  ngOnInit() {
    interval(5000)
      .pipe(switchMap(() => this.statsApi.load()))
      .subscribe(s => {
        console.log('refresh');
        this.stats.set(s);
      });
  }
}

import { Subject, timer } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';

const search$ = new Subject<string>();

search$
  .pipe(switchMap(q => timer(50).pipe(map(() => `result:${q}`))))
  .subscribe(v => console.log(v));

search$.next('a');
setTimeout(() => search$.next('an'), 20);
setTimeout(() => search$.next('ang'), 100);

